#include "support/phase0_minimal_ssz.hpp"
#include "nano/consensus_altair_epoch.hpp"
using namespace test;using namespace test::phase0_minimal;
int main(){try{
 const fs::path fixtures=fs::path(NANO_TEST_SOURCE)/"tests/fixtures",root=fixtures/"consensus-altair-rewards-official",refs=fixtures/"consensus-slashing-official",altair=fixtures/"consensus-altair-state-roots-official";
 const auto preset=read(refs/"minimal-phase0.yaml"),config=read(refs/"minimal-config.yaml"),ap=read(altair/"minimal-altair.yaml");auto p=[&](const char* k){return parameter(preset,k);};
 const auto rm=load(refs/"manifest.json");for(const char* file:{"minimal-phase0.yaml","minimal-config.yaml"})check(hex(sha256(binary(refs/file))).substr(2)==rm.at("referenceFiles").at(file).at("sha256").get<std::string>(),"reward rule digest");const auto am=load(altair/"manifest.json");check(hex(sha256(binary(altair/"minimal-altair.yaml"))).substr(2)==am.at("referenceFiles").at("minimal-altair.yaml").at("sha256").get<std::string>(),"Altair preset digest");
 const AltairStateLimits l{p("SLOTS_PER_HISTORICAL_ROOT"),p("EPOCHS_PER_HISTORICAL_VECTOR"),p("EPOCHS_PER_SLASHINGS_VECTOR"),p("HISTORICAL_ROOTS_LIMIT"),p("EPOCHS_PER_ETH1_VOTING_PERIOD")*p("SLOTS_PER_EPOCH"),p("VALIDATOR_REGISTRY_LIMIT"),parameter(ap,"SYNC_COMMITTEE_SIZE")};
 // Altair consensus constants, not deployment defaults.
 const AltairRewardRules r{p("SLOTS_PER_EPOCH"),p("EFFECTIVE_BALANCE_INCREMENT"),p("BASE_REWARD_FACTOR"),parameter(config,"INACTIVITY_SCORE_BIAS"),parameter(ap,"INACTIVITY_PENALTY_QUOTIENT_ALTAIR"),p("MIN_EPOCHS_TO_INACTIVITY_PENALTY"),{14,26,14},64};
 const auto m=load(root/"manifest.json");check(m.at("commit")=="bc5c1a7fb2a8871aaffd4b16ee4dd9c72bb81908"&&m.at("cases").size()==15,"Altair rewards corpus");size_t balances=0,changed=0;
 for(const auto& row:m.at("cases")){const auto name=row.at("name").get<std::string>();check(row.at("valid")==true,"unexpected invalid rewards case");for(const auto& [path,info]:row.at("files").items())check(hex(sha256(binary(root/path))).substr(2)==info.at("sha256").get<std::string>(),"reward fixture digest");const auto b=binary(root/name/"pre.ssz"),post=binary(root/name/"post.ssz");check(prepare_altair_rewards(b,l,r)==post,"official Altair reward post mismatch: "+name);for(size_t i=little(b,4364,4);i<little(b,6928,4);i+=8){++balances;if(little(b,i,8)!=little(post,i,8))++changed;}}
 const auto full=binary(root/"full_attestation_participation/pre.ssz"),none=binary(root/"no_attestations_all_penalties/pre.ssz");auto put=[](Bytes& b,size_t at,uint64_t n){for(size_t j=0;j<8;++j)b[at+j]=uint8_t(n>>(8*j));};unsigned rejected=0;
 auto refuse=[&](const Bytes& b,const AltairRewardRules& cfg){bool threw=false;try{prepare_altair_rewards(b,l,cfg);}catch(const std::exception&){threw=true;}check(threw,"invalid rewards accepted");++rejected;};
 auto bad=full;put(bad,little(bad,4364,4),UINT64_MAX);refuse(bad,r);bad=none;put(bad,7017,little(bad,40,8)/8);refuse(bad,r);bad=none;bad.resize(bad.size()-8);refuse(bad,r);auto cfg=r;cfg.weight_denominator=0;refuse(none,cfg);cfg=r;cfg.effective_balance_increment=0;refuse(none,cfg);cfg=r;cfg.participation_weights[0]=65;refuse(none,cfg);
 auto low=none;const auto balance_at=little(low,4364,4),flags=little(low,6928,4),score=little(low,7057,4);put(low,balance_at,0);low[flags]=4;put(low,score,0);const auto recovered=prepare_altair_rewards(low,l,r);check(little(recovered,balance_at,8)>0,"per-delta saturation lost later head reward");
 size_t calls=0;prepare_altair_rewards(full,l,r,[&]{++calls;});std::set<size_t> stops{1,2,calls/4,calls/2,3*calls/4,calls-1,calls};for(auto stop:stops){size_t n=0;bool caught=false;try{prepare_altair_rewards(full,l,r,[&]{if(++n==stop)throw std::runtime_error("cancel");});}catch(const std::runtime_error& e){caught=std::string(e.what())=="cancel";}check(caught,"cancel swallowed");}
 std::cout<<Json{{"scenario","official-altair-rewards"},{"cases",15},{"balances",balances},{"changed",changed},{"rejections",rejected},{"cancellations",stops.size()},{"perDeltaSaturation",true},{"fullEpoch",false},{"networkActive",false}}.dump()<<'\n';
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
